\documentclass{article}
\usepackage[paperwidth=841mm,paperheight=1189mm,margin=0mm]{geometry}
\usepackage{tcolorbox}
\tcbuselibrary{poster,skins,fitting}
\usepackage{graphicx}
\usepackage{amsmath,amssymb}
\usepackage{enumitem}
\usepackage[table]{xcolor}
\usepackage{lmodern}
\usepackage[T1]{fontenc}
\pagestyle{empty}

% ── Dark Theme Color Palette ──
\definecolor{primary}{HTML}{0ea5e9}     % sky blue (tech accent)
\definecolor{secondary}{HTML}{f59e0b}   % gold (wealth/finance)
\definecolor{accent}{HTML}{a855f7}      % purple (diversified)
\definecolor{bgposter}{HTML}{0B1120}    % very deep navy/slate (poster bg)
\definecolor{cardbg}{HTML}{1E293B}      % slate 800 (card bg)
\definecolor{cardtitlebg}{HTML}{0F172A} % slate 900 (card title bar)
\definecolor{textdark}{HTML}{F8FAFC}    % slate 50 (white text)
\definecolor{textgray}{HTML}{94A3B8}    % slate 400 (gray text)
\definecolor{stathighlight}{HTML}{1E293B} % stat box bg

\pagecolor{bgposter}
\color{textdark}

% ── List styling ──
\setlist[itemize]{leftmargin=24pt, itemsep=6pt, parsep=2pt, topsep=2pt,
  label={\color{secondary}$\blacktriangleright$}}
\setlist[enumerate]{leftmargin=24pt, itemsep=6pt, parsep=2pt, topsep=2pt,
  label={\color{primary}\bfseries\arabic*.}}

% ── Figure+caption macro ──
\newcommand{\posterfig}[3]{%
  \centering\includegraphics[width=#1\linewidth]{#2}\\[3mm]
  {\fontsize{26}{32}\selectfont\color{textgray}\textit{#3}}\vspace{2mm}%
}

% ── Card styles (Dark Mode) ──
\tcbset{
  darkcard/.style={
    enhanced, arc=0pt, boxrule=0pt, colback=cardbg,
    borderline west={5pt}{0pt}{primary},
    left=16pt, right=14pt, top=4pt, bottom=4pt,
    fonttitle=\fontsize{40}{48}\selectfont\bfseries\color{primary},
    coltitle=primary, colbacktitle=cardtitlebg,
    toptitle=6pt, bottomtitle=6pt,
    titlerule=2pt, titlerule style={primary!50},
    valign=top, drop shadow={opacity=0.6, shadow xshift=2pt, shadow yshift=-2pt, color=black},
    coltext=textdark
  },
  goldcard/.style={
    enhanced, arc=0pt, boxrule=0pt, colback=cardbg,
    borderline west={5pt}{0pt}{secondary},
    left=16pt, right=14pt, top=4pt, bottom=4pt,
    fonttitle=\fontsize{40}{48}\selectfont\bfseries\color{secondary},
    coltitle=secondary, colbacktitle=cardtitlebg,
    toptitle=6pt, bottomtitle=6pt,
    titlerule=2pt, titlerule style={secondary!50},
    valign=top, drop shadow={opacity=0.6, shadow xshift=2pt, shadow yshift=-2pt, color=black},
    coltext=textdark
  },
  purplecard/.style={
    enhanced, arc=0pt, boxrule=0pt, colback=cardbg,
    borderline west={5pt}{0pt}{accent},
    left=16pt, right=14pt, top=4pt, bottom=4pt,
    fonttitle=\fontsize{40}{48}\selectfont\bfseries\color{accent},
    coltitle=accent, colbacktitle=cardtitlebg,
    toptitle=6pt, bottomtitle=6pt,
    titlerule=2pt, titlerule style={accent!50},
    valign=top, drop shadow={opacity=0.6, shadow xshift=2pt, shadow yshift=-2pt, color=black},
    coltext=textdark
  },
  highlightcard/.style={
    enhanced, arc=0pt, boxrule=0pt, colback=cardtitlebg,
    borderline west={6pt}{0pt}{primary},
    left=16pt, right=14pt, top=4pt, bottom=4pt,
    fonttitle=\fontsize{40}{48}\selectfont\bfseries\color{textdark},
    coltitle=textdark, colbacktitle=primary,
    toptitle=6pt, bottomtitle=6pt,
    valign=top, drop shadow={opacity=0.7, shadow xshift=2pt, shadow yshift=-2pt, color=black},
    coltext=textdark
  },
}

\begin{document}
\begin{tcbposter}[
  coverage={spread},
  poster={columns=3, rows=20, spacing=0mm},
]

% ══ TITLE BAR ══
\posterbox[
  enhanced, colback=cardtitlebg, colframe=primary, colupper=textdark,
  arc=0pt, boxrule=0pt, borderline south={4pt}{0pt}{primary},
  left=40pt, right=40pt, top=12pt, bottom=8pt,
  halign=center, valign=center,
  drop shadow={opacity=0.6, color=black}
]{name=title, column=1, span=3, between=top and row3}{
  {\fontsize{84}{100}\selectfont\bfseries THE WORLD'S MOST VALUABLE COMPANIES IN 2025}\\[24pt]
  {\fontsize{36}{44}\selectfont\color{primary} A comparative snapshot of the top publicly traded companies by market capitalization}\\[8pt]
  {\fontsize{30}{38}\selectfont\color{textgray} Unveiling the trillion-dollar club, U.S. dominance, and sector concentration in the global economy}
}

% ══ STATS BANNER ══
\posterbox[
  enhanced, colback=bgposter, boxrule=0pt, arc=0pt,
  left=12pt, right=12pt, top=6pt, bottom=6pt,
  valign=center
]{name=stats, column=1, span=3, between=row3 and row5}{
  \centering
  \begin{minipage}[c]{0.235\linewidth}\centering
    \fcolorbox{primary!40}{stathighlight}{\parbox{0.88\linewidth}{%
      \centering\vspace{12pt}%
      {\fontsize{66}{80}\selectfont\bfseries\color{primary} \$4.82 T}\\[12pt]
      {\fontsize{26}{32}\selectfont\color{textdark} NVIDIA Market Cap}\\[4pt]
      {\fontsize{22}{28}\selectfont\color{textgray} (Rank \#1)}\vspace{12pt}%
    }}
  \end{minipage}\hfill
  \begin{minipage}[c]{0.235\linewidth}\centering
    \fcolorbox{primary!40}{stathighlight}{\parbox{0.88\linewidth}{%
      \centering\vspace{12pt}%
      {\fontsize{66}{80}\selectfont\bfseries\color{primary} \sim\$25.4 T}\\[12pt]
      {\fontsize{26}{32}\selectfont\color{textdark} Top 10 Combined Value}\\[4pt]
      {\fontsize{22}{28}\selectfont\color{textgray} (\sim 18\% of global market)}\vspace{12pt}%
    }}
  \end{minipage}\hfill
  \begin{minipage}[c]{0.235\linewidth}\centering
    \fcolorbox{primary!40}{stathighlight}{\parbox{0.88\linewidth}{%
      \centering\vspace{12pt}%
      {\fontsize{66}{80}\selectfont\bfseries\color{primary} 15 of 20}\\[12pt]
      {\fontsize{26}{32}\selectfont\color{textdark} U.S. Companies}\\[4pt]
      {\fontsize{22}{28}\selectfont\color{textgray} (Dominating the Top 20)}\vspace{12pt}%
    }}
  \end{minipage}\hfill
  \begin{minipage}[c]{0.235\linewidth}\centering
    \fcolorbox{primary!40}{stathighlight}{\parbox{0.88\linewidth}{%
      \centering\vspace{12pt}%
      {\fontsize{66}{80}\selectfont\bfseries\color{primary} \$142.9 T}\\[12pt]
      {\fontsize{26}{32}\selectfont\color{textdark} Total Global Market Cap}\\[4pt]
      {\fontsize{22}{28}\selectfont\color{textgray} (Across 10,796 companies)}\vspace{12pt}%
    }}
  \end{minipage}
}

% ══ THE TRILLION-DOLLAR CLUB ══
\posterbox[darkcard, title={The Trillion-Dollar Club}
]{name=club, column=1, span=2, between=row5 and row16}{
  \fontsize{34}{44}\selectfont
  Eleven companies have crossed the trillion-dollar threshold, commanding a massive share of global market value. The gap between the top 5 and the rest is stark:\\[24pt]

  \renewcommand{\arraystretch}{1.6}
  \begin{tabular}{r l l l p{0.45\linewidth}}
    \rowcolor{bgposter}
    \bfseries \# & \bfseries Company & \bfseries Ticker & \bfseries Market Cap & \bfseries Relative Scale \\
    \bfseries 1 & NVIDIA & NVDA & \$4.82 T & \textcolor{primary}{\rule{0.45\linewidth}{24pt}} \\
    \rowcolor{bgposter}
    \bfseries 2 & Alphabet & GOOG & \$4.03 T & \textcolor{primary!85}{\rule{0.376\linewidth}{24pt}} \\
    \bfseries 3 & Apple & AAPL & \$3.87 T & \textcolor{primary!85}{\rule{0.361\linewidth}{24pt}} \\
    \rowcolor{bgposter}
    \bfseries 4 & Microsoft & MSFT & \$3.12 T & \textcolor{primary!85}{\rule{0.291\linewidth}{24pt}} \\
    \bfseries 5 & Amazon & AMZN & \$2.69 T & \textcolor{primary!85}{\rule{0.251\linewidth}{24pt}} \\
    \rowcolor{bgposter}
    \bfseries 6 & Broadcom & AVGO & \$1.89 T & \textcolor{secondary}{\rule{0.176\linewidth}{24pt}} \\
    \bfseries 7 & TSMC & TSM & \$1.88 T & \textcolor{secondary}{\rule{0.175\linewidth}{24pt}} \\
    \rowcolor{bgposter}
    \bfseries 8 & Saudi Aramco & 2222.SR & \$1.77 T & \textcolor{accent}{\rule{0.165\linewidth}{24pt}} \\
    \bfseries 9 & Meta Platforms & META & \$1.71 T & \textcolor{secondary}{\rule{0.159\linewidth}{24pt}} \\
    \rowcolor{bgposter}
    \bfseries 10 & Tesla & TSLA & \$1.46 T & \textcolor{accent}{\rule{0.136\linewidth}{24pt}} \\
    \bfseries 11 & Berkshire Hathaway & BRK-B & \$1.02 T & \textcolor{accent}{\rule{0.095\linewidth}{24pt}} \\
  \end{tabular}\\[32pt]

  \colorbox{primary!20}{\parbox{0.94\linewidth}{
    \centering\textbf{The Top 5 alone are worth over \$18.5 trillion} — ~13\% of all tracked public company value.
  }}
}

% ══ SECTOR CONCENTRATION ══
\posterbox[purplecard, title={Sector Concentration}
]{name=sector, column=3, between=row5 and row11}{
  \fontsize{34}{44}\selectfont
  Technology and semiconductor companies overwhelmingly dominate the highest market cap positions.\\[16pt]
  \begin{itemize}[itemsep=16pt]
    \item \textbf{Tech Reigns Supreme:} NVIDIA, Broadcom, TSMC, and Apple drive massive valuation from chips and consumer hardware.
    \item \textbf{Software \& Platforms:} Alphabet, Microsoft, Amazon, and Meta fill out the software and internet tiers.
    \item \textbf{The Exceptions:} Only three non-tech entries crack the top 11:
      \begin{itemize}[itemsep=8pt]
        \item Saudi Aramco (Oil \& Gas)
        \item Tesla (Automotive / Energy)
        \item Berkshire Hathaway (Investment)
      \end{itemize}
  \end{itemize}
}

% ══ COUNTRY DOMINANCE ══
\posterbox[goldcard, title={Country Dominance}
]{name=country, column=3, between=row11 and row16}{
  \fontsize{34}{44}\selectfont
  The United States commands the global hierarchy, holding \textbf{15 of the top 20} spots.\\[16pt]
  The remaining five companies are distributed globally:\\[8pt]
  \begin{itemize}[itemsep=16pt]
    \item \textbf{Taiwan:} TSMC (Rank 7)
    \item \textbf{Saudi Arabia:} Saudi Aramco (Rank 8)
    \item \textbf{China:} Tencent (Rank 18)
    \item \textbf{South Korea:} Samsung (Rank 21)
    \item \textbf{Netherlands:} ASML (Rank 20)
  \end{itemize}
}

% ══ PUTTING IT IN PERSPECTIVE ══
\posterbox[highlightcard, title={Scale in Context}
]{name=perspective, column=1, span=3, between=row16 and bottom}{
  \fontsize{34}{44}\selectfont
  The gap between the very top and the broader market reveals extreme global concentration:\\[24pt]

  \begin{minipage}[t]{0.31\linewidth}
    \colorbox{primary!25}{\parbox{\linewidth}{
      \centering\vspace{16pt}%
      {\fontsize{42}{50}\selectfont\bfseries NVIDIA Alone}\\[12pt]
      Worth more than the combined market cap of the \textbf{bottom 5,000+} tracked companies globally.\vspace{16pt}%
    }}
  \end{minipage}\hfill
  \begin{minipage}[t]{0.31\linewidth}
    \colorbox{secondary!25}{\parbox{\linewidth}{
      \centering\vspace{16pt}%
      {\fontsize{42}{50}\selectfont\bfseries The 0.09\%}\\[12pt]
      The top 10 companies hold \textbf{17.8\% of total global market value}, despite 10,796 total firms.\vspace{16pt}%
    }}
  \end{minipage}\hfill
  \begin{minipage}[t]{0.31\linewidth}
    \colorbox{accent!25}{\parbox{\linewidth}{
      \centering\vspace{16pt}%
      {\fontsize{42}{50}\selectfont\bfseries The 9x Drop}\\[12pt]
      Moving from Rank 1 (\$4.82 T) to Rank 20 (\$554 B) represents a massive \textbf{nearly 9x drop} in valuation.\vspace{16pt}%
    }}
  \end{minipage}
}

\end{tcbposter}
\end{document}

